import React, { useState } from "react";
import { productList as initialProducts } from "../data/productimage";


const Products = () => {
  const [products, setProducts] = useState(initialProducts);
  const [showForm, setShowForm] = useState(false);

  // Form fields
  const [formData, setFormData] = useState({
    name: "",
    category: "",
    price: "",
    brand: "",
    image: "",
  });

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // Add product
  const handleAddProduct = (e) => {
    e.preventDefault();
    const newProduct = {
      ...formData,
      price: Number(formData.price), // ensure price is a number
    };
    setProducts([newProduct, ...products]); // Add to beginning of list
    setFormData({ name: "", category: "", price: "", brand: "", image: "" }); // reset form
    setShowForm(false); // close modal
  };

  return (
    <div>
      <h1 style={{ textAlign: "center", marginTop: "40px" }}>PRODUCTS</h1>

      <div style={{ textAlign: "center", margin: "20px" }}>
        <button className="add-product-btn" onClick={() => setShowForm(true)}>
          Add Product
        </button>
      </div>

      {/* Modal Form */}
      {showForm && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h2>Add New Product</h2>
            <form onSubmit={handleAddProduct}>
              <input
                type="text"
                name="name"
                placeholder="Name"
                value={formData.name}
                onChange={handleChange}
                required
              />
              <input
                type="text"
                name="category"
                placeholder="Category"
                value={formData.category}
                onChange={handleChange}
                required
              />
              <input
                type="number"
                name="price"
                placeholder="Price"
                value={formData.price}
                onChange={handleChange}
                required
              />
              <input
                type="text"
                name="brand"
                placeholder="Brand"
                value={formData.brand}
                onChange={handleChange}
                required
              />
              <input
                type="url"
                name="image"
                placeholder="Image URL"
                value={formData.image}
                onChange={handleChange}
                required
              />
              <div className="form-buttons">
                <button type="submit" className="square-btn view">
                  Submit
                </button>
                <button
                  type="button"
                  className="square-btn delete"
                  onClick={() => setShowForm(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Product Grid */}
      <div className="product-grid">
        {products.map((product, index) => (
          <div key={index} className="square-card">
            <img src={product.image} alt={product.name} className="square-img" />
            <div className="square-info">
              <h4>{product.name}</h4>
              <p className="product-meta">{product.category}</p>
              <p className="product-meta">₹{product.price}</p>
              <p className="product-meta">{product.brand}</p>
            </div>
            <div className="button-row">
              <button className="square-btn delete">Delete</button>
              <button className="square-btn view">View</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Products;
